#include <print>
#include <memory>
#include <string>

void peek(const int* p) { if (p) std::println("看一眼: {}", *p); }

int main() {
    std::string best = "值类型";
    auto up = std::make_unique<int>(10);
    std::println("① 值: {}", best);
    std::println("② unique_ptr: {}", *up);
    peek(up.get());
    peek(nullptr);
    return 0;
}
// 以前这里是 int* p = new int(10); 用完 delete p;，现在换成 make_unique，收尾不用再操心

